SELECT p.order_id,p.order_status,p.order_purchase_timestamp,p.order_estimated_delivery_date,p.order_delivered_customer_date,g.customer_state,g.customer_city,p.payment_value_total,p.review_score FROM dw.FactPedidos p JOIN dw.DimGeografiaCliente g ON g.geografia_cliente_key=p.geografia_cliente_key WHERE p.order_id=@OrderId AND LEN(@OrderId) BETWEEN 1 AND 64;
